      path: '/:pathMatch(.*)*',
      redirect: '/'
    },
  ]
})

router.$navigate = Navigate({ $storex, $router: router })
router.$navigate.init()
router.beforeEach((to, from) => {
  return router.$navigate.onRouteChanged({ from, to })
})

window.$router = router

export default router
